import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { HostAPI } from '../dist/index.js';
import { WindowAPI, windowDTOValidators } from '../dist/window.js';

// Generated by HostWindowUsageTests from isolated synthetic Swift model owners.
const fixtures = JSON.parse(readFileSync(new URL('../fixtures/window-usage.json', import.meta.url)));
function client(results) {
  const calls = [];
  const host = new HostAPI({
    async send(request) {
      calls.push(request);
      return { version: 1, id: request.id, result: structuredClone(results[request.method]) };
    },
    subscribe() { return () => {}; }, dispose() {},
  });
  return { api: new WindowAPI(host), calls, host };
}

const applicationInventory = {
  applications: [{
    id: 'future-agent', name: 'Future Agent', kind: 'cli', configurationApplication: null,
    website: 'https://example.invalid', icon: null, installed: true, configurationFound: false,
    installations: [{
      id: 'opaque-installation', path: '/fixture/bin/agent', resolvedPath: '/fixture/lib/agent', version: null,
      source: 'custom-source', sourceLabel: 'Custom source', active: false,
      versionCheck: { status: 'failed', latestVersion: null, checkedAt: '2026-11-06T00:00:00Z', error: 'Registry unavailable' },
      canUpgrade: false, canUninstall: false, unavailableReason: 'Source cannot be managed',
    }], canInstall: false, installUnavailableReason: 'No supported installer',
  }], scanning: false, checkingVersions: false, lastScannedAt: null, operation: null, error: null,
};

test('application inventory accepts independent catalog IDs but validates installation status and excludes credentials', () => {
  assert.deepEqual(windowDTOValidators.applicationInventory.parse(applicationInventory), applicationInventory);
  const invalid = structuredClone(applicationInventory);
  invalid.applications[0].installations[0].versionCheck.status = 'latest';
  assert.throws(() => windowDTOValidators.applicationInventory.parse(invalid), { code: 'invalid_response' });
  const credential = structuredClone(applicationInventory);
  credential.applications[0].installations[0].accessToken = 'fixture-only';
  assert.throws(() => windowDTOValidators.applicationInventory.parse(credential), { code: 'invalid_response' });
  const fakeConfiguration = structuredClone(applicationInventory);
  fakeConfiguration.applications[0].configurationApplication = 'future-agent';
  assert.throws(() => windowDTOValidators.applicationInventory.parse(fakeConfiguration), { code: 'invalid_response' });
});

test('application management binds plans to exact installations and executes using only the opaque plan ID', async () => {
  const plan = {
    id: 'opaque-plan', catalogID: 'future-agent', installationID: 'opaque-installation', action: 'uninstall',
    name: 'Future Agent', sourceLabel: 'npm', steps: ['Remove the selected installation.'], preservesData: true,
    expiresAt: '2026-11-06T01:00:00Z',
  };
  const running = { ...applicationInventory, operation: {
    id: 'operation', catalogID: 'future-agent', installationID: 'opaque-installation', action: 'uninstall',
    status: 'running', startedAt: '2026-11-06T00:00:00Z', finishedAt: null, error: null, output: '',
  } };
  const { api, host, calls } = client({
    'applications.inventory': applicationInventory,
    'applications.checkVersions': { ...applicationInventory, checkingVersions: true },
    'applications.planOperation': plan,
    'applications.executeOperation': running,
  });
  try {
    await api.applicationsInventory();
    await api.applicationsInventory({ refresh: true });
    await api.applicationsCheckVersions({ catalogID: undefined });
    await api.applicationsCheckVersions({ catalogID: 'future-agent' });
    assert.deepEqual(await api.applicationsPlanOperation({ catalogID: 'future-agent', installationID: 'opaque-installation', action: 'uninstall' }), plan);
    assert.equal((await api.applicationsExecuteOperation({ planID: plan.id })).operation.status, 'running');
    assert.deepEqual(calls.map(({ method, params }) => ({ method, params })), [
      { method: 'applications.inventory', params: {} },
      { method: 'applications.inventory', params: { refresh: true } },
      { method: 'applications.checkVersions', params: {} },
      { method: 'applications.checkVersions', params: { catalogID: 'future-agent' } },
      { method: 'applications.planOperation', params: { catalogID: 'future-agent', installationID: 'opaque-installation', action: 'uninstall' } },
      { method: 'applications.executeOperation', params: { planID: 'opaque-plan' } },
    ]);
  } finally { api.dispose(); host.dispose(); }
});

test('window SDK accepts real Swift DTOs across all statistics routes', async () => {
  const { api, host } = client(fixtures);
  try {
    await api.usageOverview({});
    await api.conversationsList({});
    await api.conversationDetail('fixture');
    await api.projectsList({});
    await api.projectDetail({});
    await api.quotaAnalytics({});
    await api.usageRefresh();
  } finally { api.dispose(); host.dispose(); }
});

test('window DTO validation rejects extra credential fields and invalid money', () => {
  const dto = structuredClone(fixtures['conversations.detail']);
  assert.throws(() => windowDTOValidators.conversationDetail.parse({ ...dto, accessToken: 'fixture-only' }), { code: 'invalid_response' });
  const overview = structuredClone(fixtures['window.usage.overview']);
  overview.totals.costUSD = '$12.00';
  assert.throws(() => windowDTOValidators.usageOverview.parse(overview), { code: 'invalid_response' });
});

test('pricing display strings accept formatted currency while source prices stay decimal', () => {
  const usage = fixtures['usage.refresh'];
  const price = { input: '1.25', output: '2.5', cacheRead: '0.1', cacheCreation: '0' };
  const displayPrice = { input: '¥8.75', output: '¥17.50', cacheRead: '¥0.70', cacheCreation: '¥0.00' };
  const dto = { providers: [{ id: 'fixture', name: 'Fixture', models: [{ id: 'fixture', name: 'Fixture', price, displayPrice }] }], fetchedAt: null, refreshFailed: false, usage };
  assert.deepEqual(windowDTOValidators.pricingCatalog.parse(dto), dto);
});

test('optional fields are omitted and disposed windows cannot dispatch', async () => {
  const { api, host, calls } = client(fixtures);
  try {
    await api.conversationDetail('fixture', undefined);
    assert.deepEqual(calls[0].params, { id: 'fixture' });
    api.dispose();
    await assert.rejects(api.projectsList({}), { code: 'disposed' });
    assert.equal(calls.length, 1);
  } finally { host.dispose(); }
});

test('account and settings projections from Swift match the window contract', () => {
  for (const [file, validator] of [['window-settings.json', 'settings'], ['window-accounts.json', 'quotaAccounts']]) {
    const dto = JSON.parse(readFileSync(new URL('../fixtures/' + file, import.meta.url)));
    assert.deepEqual(windowDTOValidators[validator].parse(dto), dto);
  }
});

test('dashboard routes validate DTOs and forward filters', async () => {
  const totals = fixtures['window.usage.overview'].totals;
  const status = fixtures['usage.refresh'];
  const coverage = { precision: 'day', incomplete: true, refreshing: true, unlocatedTotals: totals, message: null };
  const sample = { key: '2026-01-01T00:00:00Z', start: '2026-01-01T00:00:00Z', totals, value: 0, label: '0', normalizedValue: 0, segments: [{ service: 'codex', totals, value: 0, label: '0', share: 0 }] };
  const dashboard = { requestLogCount: null, kpiDisplay: { cost: '$0', requests: '0', tokens: '0', cacheHitRate: '0%' }, revision: '1', resolvedRange: { from: '2026-01-01T00:00:00Z', to: '2026-01-02T00:00:00Z', timeZone: 'UTC', granularity: 'hour', asOf: '2026-01-02T00:00:00Z' }, coverage, totals, facets: { services: [], sources: [], models: [] }, providerRows: [], modelRows: [], samples: [sample], axisTicks: [], status };
  const results = { 'window.usage.dashboard': dashboard, 'window.usage.requests': { revision: '1', resolvedRange: dashboard.resolvedRange, totalCount: 0, page: 1, pageSize: 12, rows: [], nextCursor: null, coverage, status }, 'window.usage.heatmap': { fromDay: '2025-01-01', toDay: '2026-01-01', timeZone: 'UTC', cumulativeFromDay: null, days: [], totals, nextBeforeDay: null, coverage, status } };
  const { api, host, calls } = client(results);
  try {
    const query = { range: 'today', metric: 'cost', service: 'codex' };
    assert.deepEqual(await api.usageDashboard(query), dashboard);
    await api.usageRequests({ ...query, page: 3, pageSize: 24 });
    await api.usageHeatmap(query);
    assert.equal(calls[1].params.page, 3);
    assert.equal(calls[1].params.pageSize, 24);
    assert.equal(windowDTOValidators.usageDashboard.parse({ ...dashboard, requestLogCount: 7 }).requestLogCount, 7);
    const { requestLogCount, ...missingCount } = dashboard;
    assert.throws(() => windowDTOValidators.usageDashboard.parse(missingCount), { code: 'invalid_response' });
    const { pageSize, ...missingPageSize } = results['window.usage.requests'];
    assert.throws(() => windowDTOValidators.usageRequests.parse(missingPageSize), { code: 'invalid_response' });
    assert.throws(() => windowDTOValidators.usageDashboard.parse({ ...dashboard, credential: 'secret' }), { code: 'invalid_response' });
    const { segments, ...missingSegments } = sample;
    assert.throws(() => windowDTOValidators.usageDashboard.parse({ ...dashboard, samples: [missingSegments] }), { code: 'invalid_response' });
    assert.throws(() => windowDTOValidators.usageDashboard.parse({ ...dashboard, samples: [{ ...sample, segments: [{ ...segments[0], service: 'unknown' }] }] }), { code: 'invalid_response' });
    const { refreshing, ...missingRefreshing } = coverage;
    assert.throws(() => windowDTOValidators.usageDashboard.parse({ ...dashboard, coverage: missingRefreshing }), { code: 'invalid_response' });
  } finally { api.dispose(); host.dispose(); }
});

function heatmapDTO() {
  const totals = fixtures['window.usage.overview'].totals;
  return {
    fromDay: '2025-01-06', toDay: '2026-01-12', timeZone: 'UTC',
    cumulativeFromDay: '2024-02-29',
    days: [{ day: '2025-01-06', totals, value: 12.5, label: '$12.50', normalizedValue: 1, cumulativeTokens: 5_000_000 + totals.totalTokens }],
    totals, nextBeforeDay: '2025-01-06',
    coverage: { precision: 'day', incomplete: false, refreshing: false, unlocatedTotals: totals, message: null },
    status: fixtures['usage.refresh'],
  };
}

test('heatmap preserves host history totals before the visible window and forwards filters', async () => {
  const dto = heatmapDTO();
  const { api, host, calls } = client({ 'window.usage.heatmap': dto });
  try {
    const query = { range: 'all', metric: 'cost', service: 'codex', sourceID: 'source-fixture', modelID: 'model-fixture' };
    const result = await api.usageHeatmap(query);
    assert.deepEqual(result, dto);
    assert.deepEqual(calls[0].params, query);
    assert.equal(result.days[0].cumulativeTokens - result.days[0].totals.totalTokens, 5_000_000);
    assert.ok(result.cumulativeFromDay < result.fromDay);
  } finally { api.dispose(); host.dispose(); }
});

test('heatmap accepts explicit null history origin and zero cumulative Tokens', () => {
  const dto = heatmapDTO();
  dto.cumulativeFromDay = null;
  const emptyTotals = { ...dto.totals, inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheCreationTokens: 0, inputWithCacheTokens: 0, totalTokens: 0, requestCount: 0, costUSD: '0', costDisplay: '$0', cacheHitRate: 0 };
  dto.totals = emptyTotals;
  dto.coverage.unlocatedTotals = emptyTotals;
  dto.days = [{ ...dto.days[0], totals: emptyTotals, value: 0, label: '$0', normalizedValue: 0, cumulativeTokens: 0 }];
  assert.deepEqual(windowDTOValidators.usageHeatmap.parse(dto), dto);
  assert.deepEqual(windowDTOValidators.usageHeatmap.parse({ ...dto, days: [] }).days, []);
});

test('heatmap rejects missing and malformed cumulative history origins', () => {
  const dto = heatmapDTO();
  const { cumulativeFromDay, ...missing } = dto;
  assert.throws(() => windowDTOValidators.usageHeatmap.parse(missing), { code: 'invalid_response' });
  for (const invalid of [undefined, '', 0, false, '2026-1-01', '2026-02-29', '2026-02-30', '2026-13-01', '2026-01-01T00:00:00Z']) {
    assert.throws(() => windowDTOValidators.usageHeatmap.parse({ ...dto, cumulativeFromDay: invalid }), { code: 'invalid_response' }, `origin: ${String(invalid)}`);
  }
});

test('heatmap rejects missing or invalid cumulative Tokens instead of coercing them to zero', async () => {
  const dto = heatmapDTO();
  const { cumulativeTokens, ...missing } = dto.days[0];
  const missingDTO = { ...dto, days: [missing] };
  assert.throws(() => windowDTOValidators.usageHeatmap.parse(missingDTO), { code: 'invalid_response' });
  for (const invalid of [undefined, null, '0', false, -1, 0.5, NaN, Infinity, -Infinity, Number.MAX_SAFE_INTEGER + 1]) {
    assert.throws(() => windowDTOValidators.usageHeatmap.parse({ ...dto, days: [{ ...dto.days[0], cumulativeTokens: invalid }] }), { code: 'invalid_response' }, `tokens: ${String(invalid)}`);
  }
  const { api, host } = client({ 'window.usage.heatmap': missingDTO });
  try {
    await assert.rejects(api.usageHeatmap({ range: 'all', metric: 'tokens' }), { code: 'invalid_response' });
  } finally { api.dispose(); host.dispose(); }
});

test('bootstrap requires visible usage services and validates each service', () => {
  const dto = { route: { page: 'stats' }, language: 'system', resolvedLanguage: 'en', platform: 'macos', timeZone: 'UTC', appearance: 'light', version: 'test', sidebarApplications: [], visibleUsageServices: ['codex', 'claude'], capabilities: [] };
  assert.deepEqual(windowDTOValidators.bootstrap.parse(dto), dto);
  const { visibleUsageServices, ...missing } = dto;
  assert.throws(() => windowDTOValidators.bootstrap.parse(missing), { code: 'invalid_response' });
  assert.throws(() => windowDTOValidators.bootstrap.parse({ ...dto, visibleUsageServices: ['unknown'] }), { code: 'invalid_response' });
});
